struct TPPLPoly {
    hole: bool,
    numpoints: usize,
    points: Option<Vec<TPPLPoint>>, // Replaced dynamic allocation with Vec
}

impl TPPLPoly {
    pub fn new() -> Self {
        TPPLPoly {
            hole: false,
            numpoints: 0,
            points: None,
        }
    }

    pub fn clear(&mut self) {
        self.points.take(); // Dispose of the vector which drops memory
        self.hole = false;
        self.numpoints = 0;
    }

    pub fn init(&mut self, numpoints: usize) {
        self.clear();
        self.numpoints = numpoints;
        self.points = Some(vec![TPPLPoint { x: 0.0, y: 0.0 }; numpoints]);
    }

    pub fn triangle(&mut self, p1: TPPLPoint, p2: TPPLPoint, p3: TPPLPoint) {
        self.init(3);
        self.points.as_mut().unwrap()[0] = p1;
        self.points.as_mut().unwrap()[1] = p2;
        self.points.as_mut().unwrap()[2] = p3;
    }

    pub fn get_orientation(&self) -> TPPLOrientation {
        let mut area: tppl_float = 0.0;
        let points = self.points.as_ref().unwrap();
        for i1 in 0..self.numpoints {
            let i2 = (i1 + 1) % self.numpoints;
            area += points[i1].x * points[i2].y - points[i1].y * points[i2].x;
        }
        if area > 0.0 {
            TPPL_ORIENTATION_CCW
        } else if area < 0.0 {
            TPPL_ORIENTATION_CW
        } else {
            TPPL_ORIENTATION_NONE
        }
    }

    pub fn set_orientation(&mut self, orientation: TPPLOrientation) {
        let polyorientation = self.get_orientation();
        if polyorientation != TPPL_ORIENTATION_NONE && polyorientation != orientation {
            self.invert();
        }
    }

    pub fn invert(&mut self) {
        if let Some(points) = &mut self.points {
            points.reverse();
        }
    }

    pub fn is_hole(&self) -> bool {
        self.hole
    }

    pub fn get_num_points(&self) -> usize {
        self.numpoints
    }

    pub fn get_points(&self) -> &[TPPLPoint] {
        self.points.as_deref().unwrap()
    }

    pub fn get_points_mut(&mut self) -> &mut [TPPLPoint] {
        self.points.as_mut().unwrap()
    }

    pub fn get_point(&self, index: usize) -> TPPLPoint {
        self.points.as_ref().unwrap()[index]
    }
