const TPPL_ORIENTATION_CCW: TPPLOrientation = 1;
const TPPL_ORIENTATION_CW: TPPLOrientation = -1;
const TPPL_ORIENTATION_NONE: TPPLOrientation = 0;

struct TPPLPartition;

impl TPPLPartition {
    fn normalize(p: &TPPLPoint) -> TPPLPoint {
        let n = tppl_sqrt(p.x * p.x + p.y * p.y);
        if n != 0.0 {
            TPPLPoint {
                x: p.x / n,
                y: p.y / n,
            }
        } else {
            TPPLPoint { x: 0.0, y: 0.0 }
        }
    }

    fn distance(p1: &TPPLPoint, p2: &TPPLPoint) -> tppl_float {
        let dx = p2.x - p1.x;
        let dy = p2.y - p1.y;
        tppl_sqrt(dx * dx + dy * dy)
    }

    fn intersects(p11: &TPPLPoint, p12: &TPPLPoint, p21: &TPPLPoint, p22: &TPPLPoint) -> bool {
        if p11 == p21 || p11 == p22 || p12 == p21 || p12 == p22 {
            return false;
        }

        let v1ort = TPPLPoint {
            x: p12.y - p11.y,
            y: p11.x - p12.x,
        };
        let v2ort = TPPLPoint {
            x: p22.y - p21.y,
            y: p21.x - p22.x,
        };

        let mut v = TPPLPoint {
            x: p21.x - p11.x,
            y: p21.y - p11.y,
        };
        let dot21 = v.x * v1ort.x + v.y * v1ort.y;
        v.x = p22.x - p11.x;
        v.y = p22.y - p11.y;
        let dot22 = v.x * v1ort.x + v.y * v1ort.y;

        v.x = p11.x - p21.x;
        v.y = p11.y - p21.y;
        let dot11 = v.x * v2ort.x + v.y * v2ort.y;
        v.x = p12.x - p21.x;
        v.y = p12.y - p21.y;
        let dot12 = v.x * v2ort.x + v.y * v2ort.y;

        dot11 * dot12 <= 0.0 && dot21 * dot22 <= 0.0
    }

    fn is_convex(p1: &TPPLPoint, p2: &TPPLPoint, p3: &TPPLPoint) -> bool {
        let tmp = (p3.y - p1.y) * (p2.x - p1.x) - (p3.x - p1.x) * (p2.y - p1.y);
        tmp > 0.0
    }

    fn is_reflex(p1: &TPPLPoint, p2: &TPPLPoint, p3: &TPPLPoint) -> bool {
        let tmp = (p3.y - p1.y) * (p2.x - p1.x) - (p3.x - p1.x) * (p2.y - p1.y);
        tmp < 0.0
    }

    fn is_inside(p1: &TPPLPoint, p2: &TPPLPoint, p3: &TPPLPoint, p: &TPPLPoint) -> bool {
        !TPPLPartition::is_convex(p1, p, p2)
            && !TPPLPartition::is_convex(p2, p, p3)
            && !TPPLPartition::is_convex(p3, p, p1)
    }

    fn in_cone(p1: &TPPLPoint, p2: &TPPLPoint, p3: &TPPLPoint, p: &TPPLPoint) -> bool {
        let convex = TPPLPartition::is_convex(p1, p2, p3);

        if convex {
            TPPLPartition::is_convex(p1, p2, p) && TPPLPartition::is_convex(p2, p3, p)
        } else {
            TPPLPartition::is_convex(p1, p2, p) || TPPLPartition::is_convex(p2, p3, p)
        }
    }

    fn is_below(p1: &TPPLPoint, p2: &TPPLPoint) -> bool {
        p1.y < p2.y || (p1.y == p2.y && p1.x < p2.x)
    }
}

