type TpplFloat = f64;

#[derive(Clone, Copy, PartialEq)]
struct TPPLPoint {
    x: TpplFloat,
    y: TpplFloat,
}

impl TPPLPoint {
    fn new(x: TpplFloat, y: TpplFloat) -> Self {
        Self { x, y }
    }

    fn distance(&self, other: &TPPLPoint) -> TpplFloat {
        ((self.x - other.x).powi(2) + (self.y - other.y).powi(2)).sqrt()
    }

    fn subtract(&self, other: &TPPLPoint) -> TPPLPoint {
        TPPLPoint::new(self.x - other.x, self.y - other.y)
    }

    fn normalize(&self) -> TPPLPoint {
        let norm = self.x.hypot(self.y);
        if norm != 0.0 {
            TPPLPoint::new(self.x / norm, self.y / norm)
        } else {
            TPPLPoint::new(0.0, 0.0)
        }
    }
}

