impl TPPLPoly {
    fn new() -> Self {
        Self {
            hole: false,
            numpoints: 0,
            points: Vec::new(),
        }
    }

    fn valid(&self) -> bool {
        !self.points.is_empty()
    }

    fn init(&mut self, numpoints: usize) {
        self.clear();
        self.numpoints = numpoints;
        self.points = vec![TPPLPoint::new(0.0, 0.0); numpoints];
    }

    fn clear(&mut self) {
        self.hole = false;
        self.numpoints = 0;
        self.points.clear();
    }

    fn triangle(&mut self, p1: TPPLPoint, p2: TPPLPoint, p3: TPPLPoint) {
        self.init(3);
        self.points[0] = p1;
        self.points[1] = p2;
        self.points[2] = p3;
    }

    fn get_orientation(&self) -> TPPLOrientation {
        let mut area = 0.0;
        for i in 0..self.numpoints {
            let i2 = (i + 1) % self.numpoints;
            area += self.points[i].x * self.points[i2].y - self.points[i].y * self.points[i2].x;
        }
        if area > 0.0 {
            TPPLOrientation::CCW
        } else if area < 0.0 {
            TPPLOrientation::CW
        } else {
            TPPLOrientation::None
        }
    }

    fn set_orientation(&mut self, orientation: TPPLOrientation) {
        let poly_orientation = self.get_orientation();
        if poly_orientation != TPPLOrientation::None && poly_orientation != orientation {
            self.invert();
        }
    }

    fn invert(&mut self) {
        self.points.reverse();
    }
}

