            points[1] = p2;
            points[2] = p3;
        }
    }

    fn get_orientation(&self) -> TpplOrientation {
        let mut area: TpplFloat = 0.0;
        if let Some(points) = &self.points {
            for (i, &p1) in points.iter().enumerate() {
                let p2 = points.get((i + 1) % self.numpoints).unwrap();
                area += p1.x * p2.y - p1.y * p2.x;
            }
