    fn is_convex(&self, p1: &TPPLPoint, p2: &TPPLPoint, p3: &TPPLPoint) -> bool {
        let tmp = (p3.y - p1.y) * (p2.x - p1.x) - (p3.x - p1.x) * (p2.y - p1.y);
        tmp > 0.0
    }

    fn is_reflex(&self, p1: &TPPLPoint, p2: &TPPLPoint, p3: &TPPLPoint) -> bool {
        let tmp = (p3.y - p1.y) * (p2.x - p1.x) - (p3.x - p1.x) * (p2.y - p1.y);
        tmp < 0.0
    }

    fn is_inside(&self, p1: &TPPLPoint, p2: &TPPLPoint, p3: &TPPLPoint, p: &TPPLPoint) -> bool {
        !self.is_convex(p1, p, p2) && !self.is_convex(p2, p, p3) && !self.is_convex(p3, p, p1)
    }

    fn in_cone(&self, p1: &TPPLPoint, p2: &TPPLPoint, p3: &TPPLPoint, p: &TPPLPoint) -> bool {
        self.is_convex(p1, p2, p)
            && !self.is_convex(p1, p2, p3)
            || self.is_convex(p2, p3, p)
            && !self.is_convex(p1, p2, p3)
    }
}

