            height: src.height,
            data: src.data.clone(),
        }
    }

    fn init(&mut self, width: usize, height: usize) {
        self.width = width;
        self.height = height;
        self.data = vec![0; 3 * width * height];
    }

    fn get_mean_gray(&self) -> u8 {
        let mut sum = 0u64;
        for i in 0..self.height {
            for j in 0..self.width {
                sum += self.get_pixel_gray(j, i) as u64;
            }
        }
        (sum / (self.width * self.height) as u64) as u8
    }

    fn binarize(&mut self, threshold: u8) {
        for i in 0..self.height {
            for j in 0..self.width {
                let c = self.get_pixel_gray(j, i);
                if c > threshold {
                    self.set_pixel_gray(j, i, 255);
                } else {
                    self.set_pixel_gray(j, i, 0);
                }
            }
        }
    }

    fn flip_horizontal(&mut self) {
        let mut new_data = vec![0; self.height * self.width * 3];
        for i in 0..self.height {
            for j in 0..self.width {
                let index1 = 3 * (i * self.width + j);
                let index2 = 3 * (i * self.width + self.width - j - 1);
                new_data[index1..index1 + 3].clone_from_slice(&self.data[index2..index2 + 3]);
            }
        }
        self.data = new_data;
    }

    fn flip_vertical(&mut self) {
        let mut new_data = vec![0; self.height * self.width * 3];
        for i in 0..self.height {
            for j in 0..self.width {
                let index1 = 3 * (i * self.width + j);
                let index2 = 3 * ((self.height - i - 1) * self.width + j);
                new_data[index1..index1 + 3].clone_from_slice(&self.data[index2..index2 + 3]);
            }
        }
        self.data = new_data;
    }

    fn get_pixel_bilinear(&self, x: f32, y: f32) -> Pixel {
        if x < 0.0 || y < 0.0 || x > (self.width - 1) as f32 || y > (self.height - 1) as f32 {
            return Pixel { r: 0, g: 0, b: 0 };
        }
        let x1 = x.floor() as usize;
        let y1 = y.floor() as usize;
        let dx = x - x1 as f32;
        let dy = y - y1 as f32;

        let c1 = self.get_pixel_color(x1, y1);
        let c2 = self.get_pixel_color(x1 + 1, y1);
        let c3 = self.get_pixel_color(x1, y1 + 1);
        let c4 = self.get_pixel_color(x1 + 1, y1 + 1);

        Pixel {
            r: Image::interpolate(c1.r, c2.r, c3.r, c4.r, dx, dy).round() as u8,
            g: Image::interpolate(c1.g, c2.g, c3.g, c4.g, dx, dy).round() as u8,
            b: Image::interpolate(c1.b, c2.b, c3.b, c4.b, dx, dy).round() as u8,
        }
    }

    fn interpolate(x1: u8, x2: u8, x3: u8, x4: u8, dx: f32, dy: f32) -> f32 {
        let x5 = (x2 as f32) * dx + (x1 as f32) * (1.0 - dx);
        let x6 = (x4 as f32) * dx + (x3 as f32) * (1.0 - dx);
        x6 * dy + x5 * (1.0 - dy)
    }

    fn get_histogram_gray(&self) -> [u64; 256] {
        let mut histogram = [0; 256];
        for i in 0..self.height {
            for j in 0..self.width {
                histogram[self.get_pixel_gray(j, i) as usize] += 1;
            }
        }
        histogram
    }

    fn invert(&mut self) {
        for i in 0..self.data.len() {
            self.data[i] = 255 - self.data[i];
        }
    }

    fn crop(&self, posx: usize, posy: usize, width: usize, height: usize) -> Image {
        let mut result_img = Image::with_size(width, height);
        for i in 0..height {
            for j in 0..width {
                let rgb = self.get_pixel_color(j + posx, i + posy);
                result_img.set_pixel_color(j, i, rgb);
            }
        }
        result_img
    }

    fn resize(&self, factor: usize) -> Image {
        let new_width = self.width / factor;
        let new_height = self.height / factor;
        let factor_sq = factor * factor;
        let mut result_img = Image::with_size(new_width, new_height);

        for i in 0..new_height {
            for j in 0..new_width {
                let (minx, miny) = (j * factor, i * factor);
                let (maxx, maxy) = (minx + factor, miny + factor);

                let mut sum_r = 0;
                let mut sum_g = 0;
                let mut sum_b = 0;

                for i2 in miny..maxy {
                    for j2 in minx..maxx {
                        let rgb = self.get_pixel_color(j2, i2);
                        sum_r += rgb.r as usize;
                        sum_g += rgb.g as usize;
                        sum_b += rgb.b as usize;
                    }
                }
                result_img.set_pixel_color(
                    j,
                    i,
                    Pixel {
                        r: (sum_r / factor_sq) as u8,
                        g: (sum_g / factor_sq) as u8,
                        b: (sum_b / factor_sq) as u8,
                    },
                );
            }
        }
        result_img
    }

    fn filter(&self, filter: &[f32], filter_width: usize, filter_height: usize) -> Image {
        let mut ret = Image::with_size(self.width, self.height);
        let fox = filter_width / 2;
        let foy = filter_height / 2;

        for i1 in 0..self.height {
            for j1 in 0..self.width {
                let offset1 = (i1 * self.width + j1) * 3;

                let mut sumr = 0.0;
                let mut sumg = 0.0;
                let mut sumb = 0.0;

                for i2 in 0..filter_height {
                    for j2 in 0..filter_width {
                        let x = cmp::min(
                            self.width - 1,
                            cmp::max(0, j1 as isize + j2 as isize - fox as isize) as usize,
                        );
                        let y = cmp::min(
                            self.height - 1,
                            cmp::max(0, i1 as isize + i2 as isize - foy as isize) as usize,
                        );

                        let offset2 = (y * self.width + x) * 3;
                        let offset3 = i2 * filter_width + j2;

                        sumr += self.data[offset2] as f32 * filter[offset3];
                        sumg += self.data[offset2 + 1] as f32 * filter[offset3];
                        sumb += self.data[offset2 + 2] as f32 * filter[offset3];
                    }
                }
                ret.data[offset1] = sumr.round().clamp(0.0, 255.0) as u8;
                ret.data[offset1 + 1] = sumg.round().clamp(0.0, 255.0) as u8;
                ret.data[offset1 + 2] = sumb.round().clamp(0.0, 255.0) as u8;
            }
        }
        ret
    }

    fn gauss_blur(&self, sigma: f32, mut masksize: usize) -> Image {
        if masksize == 0 {
            masksize = ((sigma.round() * 2.0 * 2.0) + 1.0) as usize;
        }

        let fsize = masksize * masksize;
        let fo = masksize / 2;
        let mut filter = vec![0.0; fsize];
        let pi = f32::consts::PI;

        for i in 0..masksize {
            for j in 0..masksize {
                let x = i as isize - fo as isize;
                let y = j as isize - fo as isize;
                filter[i * masksize + j] = (1.0 / (2.0 * pi * sigma))
                    * f32::exp(-(x.pow(2) as f32 + y.pow(2) as f32) / (2.0 * sigma * sigma));
            }
        }

        let sum: f32 = filter.iter().sum();
        for val in &mut filter {
            *val /= sum;
        }

        self.filter(&filter, masksize, masksize)
    }

    fn clear(&mut self, color: Pixel) {
        for y in 0..self.height {
            for x in 0..self.width {
                self.set_pixel_color(x, y, color);
            }
        }
    }

    fn draw_line(&mut self, x1: isize, y1: isize, x2: isize, y2: isize, color: Pixel) {
        let dx = (x2 - x1).abs();
        let dy = (y2 - y1).abs();

        if dx > dy {
            if x2 > x1 {
                for i in x1..=x2 {
                    let y = (((y2 - y1) as f32 / (x2 - x1) as f32) * (i - x1) as f32 + y1 as f32).round() as isize;
                    self.set_pixel_color(i as usize, y as usize, color);
                }
            } else {
                for i in x2..=x1 {
                    let y = (((y1 - y2) as f32 / (x1 - x2) as f32) * (i - x2) as f32 + y2 as f32).round() as isize;
                    self.set_pixel_color(i as usize, y as usize, color);
                }
            }
        } else {
            if y2 > y1 {
                for i in y1..=y2 {
                    let x = (((x2 - x1) as f32 / (y2 - y1) as f32) * (i - y1) as f32 + x1 as f32).round() as isize;
                    self.set_pixel_color(x as usize, i as usize, color);
                }
            } else {
                for i in y2..=y1 {
                    let x = (((x1 - x2) as f32 / (y1 - y2) as f32) * (i - y2) as f32 + x2 as f32).round() as isize;
                    self.set_pixel_color(x as usize, i as usize, color);
                }
            }
        }
    }

    // Helper functions for pixel access and modification

    fn get_pixel_gray(&self, x: usize, y: usize) -> u8 {
        let idx = (y * self.width + x) * 3;
        let r = self.data[idx] as u16;
        let g = self.data[idx + 1] as u16;
        let b = self.data[idx + 2] as u16;
        ((r + g + b) / 3) as u8
    }

    fn set_pixel_gray(&mut self, x: usize, y: usize, gray: u8) {
        let idx = (y * self.width + x) * 3;
        self.data[idx] = gray;
        self.data[idx + 1] = gray;
        self.data[idx + 2] = gray;
    }

    fn get_pixel_color(&self, x: usize, y: usize) -> Pixel {
        let idx = (y * self.width + x) * 3;
        Pixel {
            r: self.data[idx],
            g: self.data[idx + 1],
            b: self.data[idx + 2],
        }
    }

    fn set_pixel_color(&mut self, x: usize, y: usize, color: Pixel) {
        let idx = (y * self.width + x) * 3;
        self.data[idx] = color.r;
        self.data[idx + 1] = color.g;
        self.data[idx + 2] = color.b;
    }
}

