use std::f32;
use std::cmp;

#[derive(Clone, Copy)]
struct Pixel {
    r: u8,
    g: u8,
    b: u8,
}

struct Image {
    width: usize,
    height: usize,
    data: Vec<u8>,
}

impl Image {
    fn new() -> Image {
        Image {
            width: 0,
            height: 0,
            data: Vec::new(),
        }
    }

    fn from_dimensions(width: usize, height: usize) -> Image {
        let data = vec![0; 3 * width * height];
        Image {
            width,
            height,
            data,
        }
    }

    fn clone_from_source(src: &Image) -> Image {
        Image {
            width: src.width,
            height: src.height,
            data: src.data.clone(),
        }
    }

    fn get_mean_gray(&self) -> u8 {
        let mut sum = 0;
        for y in 0..self.height {
            for x in 0..self.width {
                sum += self.get_pixel_gray(x, y) as u64;
            }
        }
        (sum / (self.width * self.height) as u64) as u8
    }

    fn binarize(&mut self, threshold: u8) {
        for y in 0..self.height {
            for x in 0..self.width {
                let c = self.get_pixel_gray(x, y);
                self.set_pixel_gray(x, y, if c > threshold { 255 } else { 0 });
            }
        }
    }

    fn flip_horizontal(&mut self) {
        let mut new_data = vec![0u8; self.height * self.width * 3];
        for y in 0..self.height {
            for x in 0..self.width {
                let index1 = 3 * (y * self.width + x);
                let index2 = 3 * (y * self.width + (self.width - x - 1));
                new_data[index1..index1+3].copy_from_slice(&self.data[index2..index2+3]);
            }
        }
        self.data = new_data;
    }

    fn flip_vertical(&mut self) {
        let mut new_data = vec![0u8; self.height * self.width * 3];
        for y in 0..self.height {
            for x in 0..self.width {
                let index1 = 3 * (y * self.width + x);
                let index2 = 3 * (((self.height - y - 1) * self.width) + x);
                new_data[index1..index1+3].copy_from_slice(&self.data[index2..index2+3]);
            }
        }
        self.data = new_data;
    }

    fn get_pixel_bilinear(&self, x: f32, y: f32) -> Pixel {
        let mut c = Pixel { r: 0, g: 0, b: 0 };
        if x < 0.0 || y < 0.0 || x >= (self.width as f32 - 1.0) || y >= (self.height as f32 - 1.0) {
            return c;
        }

        let x1 = x.floor() as usize;
        let y1 = y.floor() as usize;
        let dx = x - x1 as f32;
        let dy = y - y1 as f32;
        let c1 = self.get_pixel_color(x1, y1);
        let c2 = self.get_pixel_color(x1 + 1, y1);
        let c3 = self.get_pixel_color(x1, y1 + 1);
        let c4 = self.get_pixel_color(x1 + 1, y1 + 1);
        c.r = Self::round(Self::interpolate(c1.r as f32, c2.r as f32, c3.r as f32, c4.r as f32, dx, dy)) as u8;
        c.g = Self::round(Self::interpolate(c1.g as f32, c2.g as f32, c3.g as f32, c4.g as f32, dx, dy)) as u8;
        c.b = Self::round(Self::interpolate(c1.b as f32, c2.b as f32, c3.b as f32, c4.b as f32, dx, dy)) as u8;
        c
    }

    fn interpolate(x1: f32, x2: f32, x3: f32, x4: f32, dx: f32, dy: f32) -> f32 {
        let x5 = x2 * dx + x1 * (1.0 - dx);
        let x6 = x4 * dx + x3 * (1.0 - dx);
        x6 * dy + x5 * (1.0 - dy)
    }

    fn round(x: f32) -> f32 {
        if (x - x.floor()) < 0.5 {
            x.floor()
        } else {
            x.ceil()
        }
    }

    fn get_histogram_gray(&self, histogram: &mut [u64]) {
        histogram.iter_mut().for_each(|x| *x = 0);
        for y in 0..self.height {
            for x in 0..self.width {
                histogram[self.get_pixel_gray(x, y) as usize] += 1;
            }
        }
    }

    fn invert(&mut self) {
        let n = 3 * self.width * self.height;
        for i in 0..n {
            self.data[i] = 255 - self.data[i];
        }
    }

    fn crop(&self, posx: usize, posy: usize, width: usize, height: usize) -> Image {
        let mut result_img = Image::from_dimensions(width, height);
        for y in 0..height {
            for x in 0..width {
                let rgb = self.get_pixel_color(x + posx, y + posy);
                result_img.set_pixel_color(x, y, rgb);
            }
        }
        result_img
    }

    fn resize(&self, factor: usize) -> Image {
        let width = self.width / factor;
        let height = self.height / factor;
        let factor2 = factor * factor;

        let mut result_img = Image::from_dimensions(width, height);
        for y in 0..height {
            for x in 0..width {
                let minx = x * factor;
                let miny = y * factor;
                let maxx = minx + factor;
                let maxy = miny + factor;

                let mut sum_r = 0.0;
                let mut sum_g = 0.0;
                let mut sum_b = 0.0;

                for i2 in miny..maxy {
                    for j2 in minx..maxx {
                        let rgb = self.get_pixel_color(j2, i2);
                        sum_r += rgb.r as f32;
                        sum_g += rgb.g as f32;
                        sum_b += rgb.b as f32;
                    }
                }
                let rgb = Pixel {
                    r: Self::round(sum_r / factor2 as f32) as u8,
                    g: Self::round(sum_g / factor2 as f32) as u8,
                    b: Self::round(sum_b / factor2 as f32) as u8,
                };
                result_img.set_pixel_color(x, y, rgb);
            }
        }
        result_img
    }

    fn filter(&self, filter: &[f32], filter_width: usize, filter_height: usize) -> Image {
        let mut ret = Image::from_dimensions(self.width, self.height);
        let fox = filter_width / 2;
        let foy = filter_height / 2;

        for i1 in 0..self.height {
            for j1 in 0..self.width {
                let offset1 = (i1 * self.width + j1) * 3;
                let mut sumr = 0.0;
                let mut sumg = 0.0;
                let mut sumb = 0.0;
                for i2 in -(foy as isize)..=(foy as isize) {
                    for j2 in -(fox as isize)..=(fox as isize) {
                        let mut x = j1 as isize + j2;
                        let mut y = i1 as isize + i2;
                        x = cmp::max(0, cmp::min(self.width as isize - 1, x));
                        y = cmp::max(0, cmp::min(self.height as isize - 1, y));
                        let offset2 = (y as usize * self.width + x as usize) * 3;
                        let offset3 = (((i2 + foy as isize) * filter_width as isize) + (j2 + fox as isize)) as usize;
                        sumr += self.data[offset2] as f32 * filter[offset3];
                        sumg += self.data[offset2 + 1] as f32 * filter[offset3];
                        sumb += self.data[offset2 + 2] as f32 * filter[offset3];
                    }
                }
                ret.data[offset1] = Self::round(sumr) as u8;
                ret.data[offset1 + 1] = Self::round(sumg) as u8;
                ret.data[offset1 + 2] = Self::round(sumb) as u8;
            }
        }
        ret
    }

    fn gauss_blur(&self, sigma: f32, mut masksize: usize) -> Image {
        if masksize == 0 {
            masksize = (Self::round(sigma) * 4.0 + 1.0) as usize;
        }

        let fsize = masksize * masksize;
        let fo = masksize / 2;
        let mut filter = vec![0.0f32; fsize];

        for i in -(fo as isize)..=(fo as isize) {
            for j in -(fo as isize)..=(fo as isize) {
                let idx = ((i + fo as isize) * masksize as isize + (j + fo as isize)) as usize;
                filter[idx] = (1.0 / (2.0 * f32::consts::PI * sigma)) * f32::exp(-((i * i + j * j) as f32) / (2.0 * sigma * sigma));
            }
        }

        let sum: f32 = filter.iter().sum();
        filter.iter_mut().for_each(|f| *f /= sum);

        self.filter(&filter, masksize, masksize)
    }

    fn clear(&mut self, color: Pixel) {
        for y in 0..self.height {
            for x in 0..self.width {
                self.set_pixel_color(x, y, color);
            }
        }
    }

    fn draw_line(&mut self, x1: i32, y1: i32, x2: i32, y2: i32, color: Pixel) {
        let dx = (x2 - x1).abs();
        let dy = (y2 - y1).abs();
        if dx > dy {
            if x2 > x1 {
                for i in x1..=x2 {
                    let y = (((y2 as f32 - y1 as f32) / (x2 - x1) as f32) * (i - x1) as f32 + y1 as f32) as i32;
                    self.set_pixel_color(i as usize, y as usize, color);
                }
            } else {
                for i in x2..=x1 {
                    let y = (((y1 as f32 - y2 as f32) / (x1 - x2) as f32) * (i - x2) as f32 + y2 as f32) as i32;
                    self.set_pixel_color(i as usize, y as usize, color);
                }
            }
        } else {
            if y2 > y1 {
                for i in y1..=y2 {
                    let x = (((x2 as f32 - x1 as f32) / (y2 - y1) as f32) * (i - y1) as f32 + x1 as f32) as i32;
                    self.set_pixel_color(x as usize, i as usize, color);
                }
            } else {
                for i in y2..=y1 {
                    let x = (((x1 as f32 - x2 as f32) / (y1 - y2) as f32) * (i - y2) as f32 + x2 as f32) as i32;
                    self.set_pixel_color(x as usize, i as usize, color);
                }
            }
        }
    }

    fn init(&mut self, width: usize, height: usize) {
        self.width = width;
        self.height = height;
        self.data = vec![0; 3 * width * height];
    }

    fn get_pixel_gray(&self, x: usize, y: usize) -> u8 {
        let idx = (y * self.width + x) * 3;
        let pixel = &self.data[idx..idx + 3];
        (0.3 * pixel[0] as f32 + 0.59 * pixel[1] as f32 + 0.11 * pixel[2] as f32) as u8
    }

    fn get_pixel_color(&self, x: usize, y: usize) -> Pixel {
        let idx = (y * self.width + x) * 3;
        Pixel {
            r: self.data[idx],
            g: self.data[idx + 1],
            b: self.data[idx + 2],
        }
    }

    fn set_pixel_gray(&mut self, x: usize, y: usize, value: u8) {
        let idx = (y * self.width + x) * 3;
        self.data[idx] = value;
        self.data[idx + 1] = value;
        self.data[idx + 2] = value;
    }

    fn set_pixel_color(&mut self, x: usize, y: usize, pixel: Pixel) {
        let idx = (y * self.width + x) * 3;
        self.data[idx] = pixel.r;
        self.data[idx + 1] = pixel.g;
        self.data[idx + 2] = pixel.b;
    }
}

