        let mut file = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };

        let (width, height) = if width == 0 || height == 0 {
            let filesize = file.metadata().map(|m| m.len()).unwrap_or(0);
            let dimension = (filesize as f64).sqrt() as u32;
            if dimension * dimension != filesize as u32 {
                eprintln!("Error loading image {}, wrong file format!", filename);
                return;
            }
            (dimension, dimension)
        } else {
            (width, height)
        };

        image.width = width;
        image.height = height;
        image.data = Some(vec![0; (image.height * image.width * 3) as usize]);

        let mut buffer = vec![0; (image.width * image.height) as usize];
        let _ = file.read_exact(&mut buffer);

        let mut pos = 0;
        for i in 0..height {
            for j in 0..width {
                let c = buffer[pos];
                image.set_pixel_gray(j, i, c);
                pos += 1;
            }
        }
    }

    pub fn save_image(filename: &str, image: &Image) {
        let img_type = Self::get_image_type(filename);
        if img_type == IMGTYPE_UNSUPPORTED {
            eprintln!("Error saving image to {}, unknown image format!", filename);
            return;
        }
        Self::save_image_with_type(filename, image, img_type);
    }

    fn save_image_with_type(filename: &str, image: &Image, image_type: i32) {
        match image_type {
            IMGTYPE_BMP => Self::save_image_bmp(filename, image),
            IMGTYPE_PPM => Self::save_image_ppm(filename, image),
            IMGTYPE_PGM => Self::save_image_pgm(filename, image),
            IMGTYPE_RAW => Self::save_image_raw(filename, image),
            _ => (),
        }
    }

    fn save_image_bmp(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };

        let mut header: Vec<u8> = vec![];
        header.extend_from_slice(b"BM");

        let row_size = ((image.width * 3 + 3) & !3) as u32;
        let file_size = 54 + row_size * image.height;
        header.extend_from_slice(&(file_size as u32).to_le_bytes());

        header.extend_from_slice(&0u16.to_le_bytes());
        header.extend_from_slice(&0u16.to_le_bytes());
        header.extend_from_slice(&54u32.to_le_bytes()); // Offset to BMP data

        header.extend_from_slice(&40u32.to_le_bytes()); // Info header size
        header.extend_from_slice(&image.width.to_le_bytes());
        header.extend_from_slice(&image.height.to_le_bytes());

        header.extend_from_slice(&1u16.to_le_bytes()); // Number of planes
        header.extend_from_slice(&24u16.to_le_bytes()); // Bits per pixel
        header.extend_from_slice(&0u32.to_le_bytes()); // Compression
        header.extend_from_slice(&0u32.to_le_bytes()); // Image size
        header.extend_from_slice(&0u32.to_le_bytes()); // Horizontal resolution
        header.extend_from_slice(&0u32.to_le_bytes()); // Vertical resolution
        header.extend_from_slice(&0u32.to_le_bytes()); // Colors in palette
        header.extend_from_slice(&0u32.to_le_bytes()); // Important colors

        let _ = file.write_all(&header);

        let row_size = row_size as usize;
        let mut row = vec![0; row_size];
        for i in 0..image.height {
            let offset = (3 * image.width * (image.height - i - 1)) as usize;
            row[..(3 * image.width) as usize].copy_from_slice(
                &image.data.as_ref().unwrap()[offset..offset + (3 * image.width) as usize],
            );
            let _ = file.write_all(&row);
        }
    }

    fn save_image_ppm(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };
        let header = format!("P6\n{} {}\n255\n", image.width, image.height);
        let _ = file.write_all(header.as_bytes());

        let size = (image.width * image.height * 3) as usize;
        file.write_all(&image.data.as_ref().unwrap()[0..size]).unwrap();
    }

    fn save_image_pgm(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };
        let header = format!("P5\n{} {}\n255\n", image.width, image.height);
        let _ = file.write_all(header.as_bytes());

        let size = (image.width * image.height) as usize;
        let mut gray_data = vec![0; size];
        for i in 0..image.height {
            for j in 0..image.width {
                gray_data[(i * image.width + j) as usize] = image.get_pixel_gray(j, i);
            }
        }
        file.write_all(&gray_data).unwrap();
    }

    fn save_image_raw(filename: &str, image: &Image) {
        let mut file = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                eprintln!("Error opening {}!", filename);
                return;
            }
        };

        let size = (image.width * image.height) as usize;
        let mut raw_data = vec![0; size];
        for i in 0..image.height {
            for j in 0..image.width {
                raw_data[(i * image.width + j) as usize] = image.get_pixel_gray(j, i);
            }
        }
        file.write_all(&raw_data).unwrap();
    }
