use std::fs::File;
use std::io::{Read, Write, Seek, SeekFrom};
use std::str;
use std::option::Option;
use std::path::{Path};

const IMGTYPE_BMP: i32 = 1;
const IMGTYPE_PPM: i32 = 2;
const IMGTYPE_PGM: i32 = 3;
const IMGTYPE_RAW: i32 = 4;
const IMGTYPE_UNSUPPORTED: i32 = -1;

pub struct Image {
    pub width: u32,
    pub height: u32,
    pub data: Option<Vec<u8>>,
}

impl Image {
    pub fn new() -> Self {
        Self {
            width: 0,
            height: 0,
            data: None,
        }
    }

    pub fn set_pixel_gray(&mut self, x: u32, y: u32, val: u8) {
        if let Some(ref mut data) = self.data {
            let index = (y * self.width + x) as usize * 3;
            data[index] = val;
            data[index + 1] = val;
            data[index + 2] = val;
        }
    }
}

pub struct Pixel {
    pub r: u8,
    pub g: u8,
    pub b: u8,
}

impl Image {
    pub fn set_pixel_color(&mut self, x: u32, y: u32, pixel: Pixel) {
        if let Some(ref mut data) = self.data {
            let index = (y * self.width + x) as usize * 3;
            data[index] = pixel.r;
            data[index + 1] = pixel.g;
            data[index + 2] = pixel.b;
        }
    }

    pub fn get_pixel_color(&self, x: u32, y: u32) -> Pixel {
        if let Some(ref data) = self.data {
            let index = (y * self.width + x) as usize * 3;
            Pixel { r: data[index], g: data[index+1], b: data[index+2] }
        } else {
            Pixel { r: 0, g: 0, b: 0 }
        }
    }

    pub fn get_pixel_gray(&self, x: u32, y: u32) -> u8 {
        if let Some(ref data) = self.data {
            let index = (y * self.width + x) as usize * 3;
            data[index]
        } else {
            0
        }
    }    
}

pub struct ImageIO;

impl ImageIO {
    pub fn get_file_extension(filename: &str) -> &str {
        let path = Path::new(filename);
        match path.extension().and_then(|s| s.to_str()) {
            Some(ext) => ext,
            None => "",
        }
    }

    pub fn get_image_type(filename: &str) -> i32 {
        let extension = Self::get_file_extension(filename);
        match extension.to_lowercase().as_str() {
            "bmp" => IMGTYPE_BMP,
            "ppm" => IMGTYPE_PPM,
            "pgm" => IMGTYPE_PGM,
            "raw" => IMGTYPE_RAW,
            _ => IMGTYPE_UNSUPPORTED,
        }
    }

    pub fn load_image(filename: &str, image: &mut Image) {
        let img_type = Self::get_image_type(filename);
        if img_type == IMGTYPE_UNSUPPORTED {
            println!("Error loading image {}, unsupported image type!", filename);
            return;
        }
        Self::load_image_with_type(filename, image, img_type);
    }

    pub fn load_image_with_type(filename: &str, image: &mut Image, image_type: i32) {
        match image_type {
            IMGTYPE_BMP => Self::load_image_bmp(filename, image),
            IMGTYPE_PPM => Self::load_image_ppm(filename, image),
            IMGTYPE_PGM => Self::load_image_pgm(filename, image),
            IMGTYPE_RAW => Self::load_image_raw(filename, image, 0, 0),
            _ => (),
        }
    }

    fn load_image_bmp(filename: &str, image: &mut Image) {
        let mut fp = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        let mut header = [0u8; 2];
        fp.read_exact(&mut header).unwrap();
        if header[0] != b'B' || header[1] != b'M' {
            println!("Error loading image {}, wrong file format!", filename);
            return;
        }

        let mut bm_offset = 0u32;
        fp.seek(SeekFrom::Start(10)).unwrap();
        fp.read_exact(unsafe { &mut *(std::slice::from_raw_parts_mut(&mut bm_offset as *mut _ as *mut u8, 4)) }).unwrap();

        let mut width = 0u32;
        let mut height = 0u32;
        fp.seek(SeekFrom::Start(18)).unwrap();
        fp.read_exact(unsafe { &mut *(std::slice::from_raw_parts_mut(&mut width as *mut _ as *mut u8, 4)) }).unwrap();
        fp.read_exact(unsafe { &mut *(std::slice::from_raw_parts_mut(&mut height as *mut _ as *mut u8, 4)) }).unwrap();

        let mut bpp = 0u16;
        fp.seek(SeekFrom::Start(28)).unwrap();
        fp.read_exact(unsafe { &mut *(std::slice::from_raw_parts_mut(&mut bpp as *mut _ as *mut u8, 2)) }).unwrap();
        if bpp != 8 && bpp != 24 {
            println!("Error loading image {}, can only load BMP files with 8 or 24 bpp!", filename);
            return;
        }

        let mut compression = 0u32;
        fp.read_exact(unsafe { &mut *(std::slice::from_raw_parts_mut(&mut compression as *mut _ as *mut u8, 4)) }).unwrap();
        if compression != 0 {
            println!("Error loading image {}, can only load uncompressed BMP files!", filename);
            return;
        }

        if let Some(ref mut data) = image.data {
            data.clear();
        }

        if bpp == 8 {
            let row_padding = (4 - (width as usize % 4)) % 4;
            let bpr = width as usize + row_padding;

            let bm_size = bpr * height as usize;
            let mut buffer = vec![0u8; bm_size];
            fp.seek(SeekFrom::Start(bm_offset as u64)).unwrap();
            fp.read_exact(&mut buffer).unwrap();

            image.width = width;
            image.height = height;
            image.data = Some(vec![0u8; (width * height * 3) as usize]);

            for i in 0..height {
                for j in 0..width {
                    let pixel_value = buffer[(i as usize * bpr + j as usize) as usize];
                    image.set_pixel_gray(j, height - i - 1, pixel_value);
                }
            }
        } else if bpp == 24 {
            let row_padding = (4 - ((width * 3) as usize % 4)) % 4;
            let bpr = (width * 3) as usize + row_padding;

            let bm_size = bpr * height as usize;
            let mut buffer = vec![0u8; bm_size];
            fp.seek(SeekFrom::Start(bm_offset as u64)).unwrap();
            fp.read_exact(&mut buffer).unwrap();

            image.width = width;
            image.height = height;
            image.data = Some(vec![0u8; (width * height * 3) as usize]);

            let mut pos = 0;
            for i in 0..height {
                for j in 0..width {
                    let rgb = Pixel {
                        b: buffer[pos],
                        g: buffer[pos + 1],
                        r: buffer[pos + 2],
                    };
                    image.set_pixel_color(j, height - i - 1, rgb);
                    pos += 3;
                }
                pos += row_padding;
            }
        }
    } 

    fn load_image_ppm(filename: &str, image: &mut Image) {
        let mut fp = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        let filesize = fp.metadata().unwrap().len();
        let mut buffer = Vec::with_capacity(filesize as usize);
        fp.read_to_end(&mut buffer).unwrap();

        let buffer_str = unsafe { str::from_utf8_unchecked(&buffer) };
        let mut header = buffer_str.split_whitespace();

        let id = header.next().unwrap();
        let sizex = header.next().unwrap().parse::<u32>().unwrap();
        let sizey = header.next().unwrap().parse::<u32>().unwrap();
        let levels = header.next().unwrap().parse::<u32>().unwrap();

        if id != "P6" || levels != 255 {
            println!("Error loading image {}, wrong file format!", filename);
            return;
        }

        image.width = sizex;
        image.height = sizey;

        if let Some(ref mut data) = image.data {
            data.clear();
        }

        image.data = Some(vec![0u8; (sizex * sizey * 3) as usize]);

        let pos = filesize as usize - (sizex * sizey * 3) as usize;
        let pixel_data = &buffer[pos..];

        let mut data = pixel_data.iter();
        for i in 0..sizey {
            for j in 0..sizex {
                let r = *data.next().unwrap();
                let g = *data.next().unwrap();
                let b = *data.next().unwrap();
                let rgb = Pixel { r, g, b };
                image.set_pixel_color(j, i, rgb);
            }
        }
    }

    fn load_image_pgm(filename: &str, image: &mut Image) {
        let mut fp = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        let filesize = fp.metadata().unwrap().len();
        let mut buffer = Vec::with_capacity(filesize as usize);
        fp.read_to_end(&mut buffer).unwrap();

        let buffer_str = unsafe { str::from_utf8_unchecked(&buffer) };
        let mut header = buffer_str.split_whitespace();

        let id = header.next().unwrap();
        let sizex = header.next().unwrap().parse::<u32>().unwrap();
        let sizey = header.next().unwrap().parse::<u32>().unwrap();
        let levels = header.next().unwrap().parse::<u32>().unwrap();

        if id != "P5" || levels != 255 {
            println!("Error loading image {}, wrong file format!", filename);
            return;
        }

        image.width = sizex;
        image.height = sizey;

        if let Some(ref mut data) = image.data {
            data.clear();
        }

        image.data = Some(vec![0u8; (sizex * sizey * 3) as usize]);

        let pos = filesize as usize - (sizex * sizey) as usize;
        let pixel_data = &buffer[pos..];

        let mut data = pixel_data.iter();
        for i in 0..sizey {
            for j in 0..sizex {
                let gray_value = *data.next().unwrap();
                image.set_pixel_gray(j, i, gray_value);
            }
        }
    }

    fn load_image_raw(filename: &str, image: &mut Image, width: u32, height: u32) {
        let mut fp = match File::open(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        let filesize = fp.metadata().unwrap().len() as u32;

        let width = if width == 0 { (filesize as f64).sqrt() as u32 } else { width };
        let height = if height == 0 { (filesize as f64).sqrt() as u32 } else { height };

        if width * height != filesize {
            println!("Error loading image {}, wrong file format!", filename);
            return;
        }

        image.width = width;
        image.height = height;

        if let Some(ref mut data) = image.data {
            data.clear();
        }

        image.data = Some(vec![0u8; (width * height * 3) as usize]);

        let mut buffer = vec![0u8; filesize as usize];
        fp.read_exact(&mut buffer).unwrap();

        let mut pos = 0;
        for i in 0..height {
            for j in 0..width {
                let gray_value = buffer[pos];
                pos += 1;
                image.set_pixel_gray(j, i, gray_value);
            }
        }
    }

    pub fn save_image(filename: &str, image: &Image) {
        let img_type = Self::get_image_type(filename);
        if img_type == IMGTYPE_UNSUPPORTED {
            println!("Error saving image to {}, unknown image format!", filename);
            return;
        }
        Self::save_image_with_type(filename, image, img_type);
    }

    pub fn save_image_with_type(filename: &str, image: &Image, image_type: i32) {
        match image_type {
            IMGTYPE_BMP => Self::save_image_bmp(filename, image),
            IMGTYPE_PPM | IMGTYPE_PGM => Self::save_image_ppm(filename, image),
            IMGTYPE_RAW => Self::save_image_raw(filename, image),
            _ => (),
        }
    }

    fn save_image_bmp(filename: &str, image: &Image) {
        let mut fp = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        let header = ['B' as u8, 'M' as u8];
        fp.write_all(&header).unwrap();

        let mut row_size = ((image.width * 3 + 3) / 4) * 4;
        let bmp_size = 54 + row_size * image.height;

        fp.write_all(&bmp_size.to_le_bytes()).unwrap();
        fp.write_all(&0u16.to_le_bytes()).unwrap(); // Reserved
        fp.write_all(&0u16.to_le_bytes()).unwrap(); // Reserved
        fp.write_all(&54u32.to_le_bytes()).unwrap(); // Data offset

        let info_header_size = 40u32;
        fp.write_all(&info_header_size.to_le_bytes()).unwrap();

        let width = image.width;
        let height = image.height;
        fp.write_all(&width.to_le_bytes()).unwrap();
        fp.write_all(&height.to_le_bytes()).unwrap();

        fp.write_all(&1u16.to_le_bytes()).unwrap(); // Planes
        fp.write_all(&24u16.to_le_bytes()).unwrap(); // Bits per pixel
        fp.write_all(&0u32.to_le_bytes()).unwrap(); // Compression
        fp.write_all(&0u32.to_le_bytes()).unwrap(); // Image size
        for _ in 0..4 { // Skip other fields
            fp.write_all(&0u32.to_le_bytes()).unwrap();
        }

        let mut row = vec![0u8; row_size as usize];

        if let Some(ref data) = image.data {
            for i in 0..height {
                let row_start = (height - i - 1) * width * 3;
                for j in 0..width * 3 {
                    row[j as usize] = data[(row_start + j) as usize];
                }
                fp.write_all(&row).unwrap();
            }
        }
    }

    fn save_image_ppm(filename: &str, image: &Image) {
        let mut fp = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        let header = format!("P6\n{} {}\n255\n", image.width, image.height);
        fp.write_all(header.as_bytes()).unwrap();

        if let Some(ref data) = image.data {
            fp.write_all(data).unwrap();
        }
    }

    fn save_image_raw(filename: &str, image: &Image) {
        let mut fp = match File::create(filename) {
            Ok(file) => file,
            Err(_) => {
                println!("Error opening {}!", filename);
                return;
            }
        };

        if let Some(ref data) = image.data {
            let gray_data: Vec<u8> = data.chunks(3).map(|chunk| chunk[0]).collect();
            fp.write_all(&gray_data).unwrap();
        }
    }
}

