struct Image {
    width: u32,
    height: u32,
    data: Vec<u8>,
}

impl Image {
    fn set_pixel_gray(&mut self, x: u32, y: u32, value: u8) {
        let offset = ((self.height - 1 - y) * self.width + x) * 3;
        self.data[offset as usize] = value;
        self.data[offset as usize + 1] = value;
        self.data[offset as usize + 2] = value;
    }

    fn set_pixel_color(&mut self, x: u32, y: u32, pixel: Pixel) {
        let offset = ((self.height - 1 - y) * self.width + x) * 3;
        self.data[offset as usize] = pixel.r;
        self.data[offset as usize + 1] = pixel.g;
        self.data[offset as usize + 2] = pixel.b;
    }

    fn get_pixel_color(&self, x: u32, y: u32) -> Pixel {
        let offset = (y * self.width + x) * 3;
        Pixel {
            r: self.data[offset as usize],
            g: self.data[offset as usize + 1],
            b: self.data[offset as usize + 2],
        }
    }

    fn get_pixel_gray(&self, x: u32, y: u32) -> u8 {
        let offset = (y * self.width + x) * 3;
        self.data[offset as usize]
    }
}

struct Pixel {
    r: u8,
    g: u8,
    b: u8,
}

struct ImageIO;

impl ImageIO {
    fn get_file_extension(filename: &str) -> &str {
        if let Some(last_slash_pos) = filename.rfind('/') {
            let filename_part = &filename[last_slash_pos + 1..];
            if let Some(dot_pos) = filename_part.rfind('.') {
                &filename_part[dot_pos + 1..]
            } else {
                ""
            }
        } else {
            if let Some(dot_pos) = filename.rfind('.') {
                &filename[dot_pos + 1..]
            } else {
                ""
            }
        }
    }

    fn get_image_type(filename: &str) -> i32 {
        match Self::get_file_extension(filename).to_lowercase().as_str() {
            "bmp" => IMGTYPE_BMP,
            "ppm" => IMGTYPE_PPM,
            "pgm" => IMGTYPE_PGM,
            "raw" => IMGTYPE_RAW,
            _ => IMGTYPE_UNSUPPORTED,
        }
    }

    fn load_image(filename: &str, image: &mut Image) -> io::Result<()> {
        let img_type = Self::get_image_type(filename);
        if img_type == IMGTYPE_UNSUPPORTED {
            eprintln!("Error loading image {}, unsupported image type!", filename);
            return Ok(());
        }
        Self::load_image_with_type(filename, image, img_type)
    }

    fn load_image_with_type(filename: &str, image: &mut Image, img_type: i32) -> io::Result<()> {
        match img_type {
            IMGTYPE_BMP => Self::load_image_bmp(filename, image),
            IMGTYPE_PPM => Self::load_image_ppm(filename, image),
            IMGTYPE_PGM => Self::load_image_pgm(filename, image),
            IMGTYPE_RAW => Self::load_image_raw(filename, image, 0, 0),
            _ => Ok(()),
        }
    }

    fn load_image_bmp(filename: &str, image: &mut Image) -> io::Result<()> {
        let mut file = File::open(filename)?;

        let mut header = [0; 2];
        file.read_exact(&mut header)?;
        if &header != b"BM" {
            eprintln!("Error loading image {}, wrong file format!", filename);
            return Ok(());
        }

        file.seek(SeekFrom::Start(10))?;
        let mut buffer = [0; 4];
        file.read_exact(&mut buffer)?;
        let bm_offset = u32::from_le_bytes(buffer);

        file.seek(SeekFrom::Start(18))?;
        let mut buffer = [0; 4];
        file.read_exact(&mut buffer)?;
        image.width = u32::from_le_bytes(buffer);

        file.read_exact(&mut buffer)?;
        image.height = u32::from_le_bytes(buffer);

        file.seek(SeekFrom::Start(28))?;
        let mut buffer = [0; 2];
        file.read_exact(&mut buffer)?;
        let bpp = u16::from_le_bytes(buffer);
        if bpp != 8 && bpp != 24 {
            eprintln!("Error loading image {}, only 8 or 24 bpp supported!", filename);
            return Ok(());
        }

        file.seek(SeekFrom::Start(30))?;
        let mut buffer = [0; 4];
        file.read_exact(&mut buffer)?;
        let compression = u32::from_le_bytes(buffer);
        if compression != 0 {
            eprintln!("Error loading image {}, only uncompressed BMP files supported!", filename);
            return Ok(());
        }

        image.data.resize(image.height as usize * image.width as usize * 3, 0);

        file.seek(SeekFrom::Start(bm_offset as u64))?;

        let row_size = ((image.width as u32 * bpp as u32 + 31) / 32) * 4;
        let mut buffer = vec![0; (row_size * image.height as u32) as usize];
        file.read_exact(&mut buffer)?;

        for i in 0..image.height {
            for j in 0..image.width {
                match bpp {
                    8 => image.set_pixel_gray(j, image.height - 1 - i, buffer[(i * row_size + j) as usize]),
                    24 => {
                        let b = buffer[(i * row_size + j * 3) as usize];
                        let g = buffer[(i * row_size + j * 3 + 1) as usize];
                        let r = buffer[(i * row_size + j * 3 + 2) as usize];
                        image.set_pixel_color(j, image.height - 1 - i, Pixel { r, g, b });
                    },
                    _ => {}
                }
            }
        }

        Ok(())
    }

    fn save_image(filename: &str, image: &Image) -> io::Result<()> {
        let img_type = Self::get_image_type(filename);
        if img_type == IMGTYPE_UNSUPPORTED {
            eprintln!("Error saving image to {}, unknown image format!", filename);
            return Ok(());
        }
        Self::save_image_with_type(filename, image, img_type)
    }

    fn save_image_with_type(filename: &str, image: &Image, img_type: i32) -> io::Result<()> {
        match img_type {
            IMGTYPE_BMP => Self::save_image_bmp(filename, image),
            IMGTYPE_PPM => Self::save_image_ppm(filename, image),
            IMGTYPE_PGM => Self::save_image_pgm(filename, image),
            IMGTYPE_RAW => Self::save_image_raw(filename, image),
            _ => Ok(()),
        }
    }

    fn save_image_bmp(filename: &str, image: &Image) -> io::Result<()> {
        let mut file = File::create(filename)?;

        file.write_all(b"BM")?;

        let row_size = ((image.width as u32 * 24 + 31) / 32) * 4;
        let file_size = 54 + row_size * image.height;

        file.write_all(&file_size.to_le_bytes())?;
        file.write_all(&[0u8; 4])?;
        file.write_all(&54u32.to_le_bytes())?;

        file.write_all(&40u32.to_le_bytes())?;
        file.write_all(&image.width.to_le_bytes())?;
        file.write_all(&image.height.to_le_bytes())?;
        file.write_all(&1u16.to_le_bytes())?;
        file.write_all(&24u16.to_le_bytes())?;
        file.write_all(&[0u8; 24])?;

        for i in 0..image.height {
            let mut row = vec![0; row_size as usize];
            for j in 0..image.width {
                let offset = ((image.height - 1 - i) * image.width + j) * 3;
                row[(j * 3) as usize] = image.data[offset as usize];
                row[(j * 3 + 1) as usize] = image.data[offset as usize + 1];
                row[(j * 3 + 2) as usize] = image.data[offset as usize + 2];
            }
            file.write_all(&row)?;
        }

        Ok(())
    }

    fn load_image_ppm(filename: &str, image: &mut Image) -> io::Result<()> {
        let mut file = File::open(filename)?;

        let mut header = [0; 1024];
        file.read(&mut header)?;
        let header = String::from_utf8_lossy(&header).to_string();
        let mut parts = header.split_whitespace();

        let id = parts.next().unwrap();
        if id != "P6" {
            eprintln!("Error loading image {}, wrong file format!", filename);
            return Ok(());
        }

        let sizes: Vec<u32> = parts.by_ref().take(2).map(|s| s.parse().unwrap()).collect();
        let levels = parts.next().unwrap();

        if levels != "255" {
            eprintln!("Error loading image {}, wrong file format!", filename);
            return Ok(());
        }

        image.width = sizes[0];
        image.height = sizes[1];
        image.data.resize((image.height * image.width * 3) as usize, 0);

        file.read_exact(&mut image.data)?;

        Ok(())
    }

    fn load_image_pgm(filename: &str, image: &mut Image) -> io::Result<()> {
        let mut file = File::open(filename)?;

        let mut header = [0; 1024];
        file.read(&mut header)?;
        let header = String::from_utf8_lossy(&header).to_string();
        let mut parts = header.split_whitespace();

        let id = parts.next().unwrap();
        if id != "P5" {
            eprintln!("Error loading image {}, wrong file format!", filename);
            return Ok(());
        }

        let sizes: Vec<u32> = parts.by_ref().take(2).map(|s| s.parse().unwrap()).collect();
        let levels = parts.next().unwrap();

        if levels != "255" {
            eprintln!("Error loading image {}, wrong file format!", filename);
            return Ok(());
        }

        image.width = sizes[0];
        image.height = sizes[1];
        image.data.resize((image.height * image.width * 3) as usize, 0);

        let buffer_size = (image.width * image.height) as usize;
        let mut buffer = vec![0; buffer_size];
        file.read_exact(&mut buffer)?;

        for (i, &val) in buffer.iter().enumerate() {
            let x = (i as u32) % image.width;
            let y = (i as u32) / image.width;
            image.set_pixel_gray(x, y, val);
        }

        Ok(())
    }

    fn save_image_ppm(filename: &str, image: &Image) -> io::Result<()> {
        let mut file = File::create(filename)?;
        write!(file, "P6\n{} {}\n255\n", image.width, image.height)?;

        file.write_all(&image.data)?;
        Ok(())
    }

    fn save_image_pgm(filename: &str, image: &Image) -> io::Result<()> {
        let mut file = File::create(filename)?;
        write!(file, "P5\n{} {}\n255\n", image.width, image.height)?;

        let mut buffer = vec![0; (image.width * image.height) as usize];
        for y in 0..image.height {
            for x in 0..image.width {
                buffer[(y * image.width + x) as usize] = image.get_pixel_gray(x, y);
            }
        }

        file.write_all(&buffer)?;
        Ok(())
    }

    fn load_image_raw(filename: &str, image: &mut Image, width: u32, height: u32) -> io::Result<()> {
        let mut file = File::open(filename)?;

        let file_len = file.metadata()?.len();
        file.seek(SeekFrom::Start(0))?;

        let pixels_len = (width * height) as u64;
        if pixels_len == 0 {
            let estimated_width = (file_len as f64).sqrt() as u32;
            if (estimated_width * estimated_width) as u64 != file_len {
                eprintln!("Error loading image {}, wrong file format!", filename);
                return Ok(());
            }
            image.width = estimated_width;
            image.height = estimated_width;
        } else {
            image.width = width;
            image.height = height;
        }

        image.data.resize(pixels_len as usize * 3, 0);

        let mut buffer = vec![0; pixels_len as usize];
        file.read_exact(&mut buffer)?;

        for (i, &val) in buffer.iter().enumerate() {
            let x = (i as u32) % image.width;
            let y = (i as u32) / image.width;
            image.set_pixel_gray(x, y, val);
        }

        Ok(())
    }

    fn save_image_raw(filename: &str, image: &Image) -> io::Result<()> {
        let mut file = File::create(filename)?;

        let mut buffer = vec![0; (image.width * image.height) as usize];

        for y in 0..image.height {
            for x in 0..image.width {
                buffer[(y * image.width + x) as usize] = image.get_pixel_gray(x, y);
            }
        }

        file.write_all(&buffer)?;
        Ok(())
    }
