fn write_poly<W: Write>(writer: &mut W, poly: &TPPLPoly) -> io::Result<()> {
    writeln!(writer, "{}", poly.get_num_points())?;

    if poly.is_hole() {
        writeln!(writer, "1")?;
    } else {
        writeln!(writer, "0")?;
    }

    for point in &poly.points {
        writeln!(writer, "{} {}", point.x, point.y)?;
    }
    Ok(())
}

